ValidationRule.errorConditionFormula:
AND(NOT( $Setup.Org_Exceptions__c.Bypass_Validation_rules__c ), OR(
AND( 
RecordType.DeveloperName  = 'Question',
ISPICKVAL(PF_Status__c, 'Closed'),

OR( 
len( Answer__c  )=0,
ISNULL(PF_Resolution_Response_Date__c)
) 
),

AND( 
RecordType.DeveloperName  <> 'Question',
ISPICKVAL(PF_Status__c, 'Closed'),

OR( 
len(PF_Resolution_Response__c )=0,
ISNULL(PF_Resolution_Response_Date__c)
) 
)

)
)
